mapper.select:
SELECT 
FROM ai_agent_dialogue_run
WHERE session_id = #{sessionId}
  AND deleted = 0
ORDER BY create_time DESC, id DESC
LIMIT #{limit}

SELECT 
FROM ai_agent_dialogue_run
WHERE session_id = #{sessionId}
  AND deleted = 0
ORDER BY create_time ASC, id ASC
LIMIT #{offset}, #{limit}

SELECT 
FROM ai_agent_dialogue_run
WHERE session_id = #{sessionId}
  AND deleted = 0

      AND (create_time > #{afterCreateTime}
           OR (create_time = #{afterCreateTime} AND id > #{afterId}))

ORDER BY create_time ASC, id ASC
LIMIT #{limit}
